<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\TahunAnggaran; use Illuminate\Http\Request; use Illuminate\Validation\Rule;
class TahunAnggaranController extends Controller { public function index(){return view('admin.years.index',['years'=>TahunAnggaran::orderByDesc('tahun')->get()]);} public function store(Request $request){$data=$request->validate(['tahun'=>'required|integer|min:2000|max:2100|unique:tahun_anggaran,tahun']); TahunAnggaran::create($data+['status'=>'nonaktif']); return back()->with('success','Tahun anggaran ditambahkan.');} public function activate(TahunAnggaran $tahunAnggaran){TahunAnggaran::query()->update(['status'=>'nonaktif']);$tahunAnggaran->update(['status'=>'aktif']);return back()->with('success',"Tahun {$tahunAnggaran->tahun} telah diaktifkan.");} }
